cd deliverable && cat > SlugTest.java <<'EOF'
public class SlugTest {
    static int failed = 0;

    static void check(String name, String actual, String expected) {
        boolean ok = actual.equals(expected);
        if (!ok) failed++;
        System.out.printf("%-22s input=%-28s -> \"%s\" (expected \"%s\") %s%n",
                name, name, actual, expected, ok ? "PASS" : "FAIL");
    }

    public static void main(String[] args) {
        check("null", LabelSlug.slug(null), "");
        check("empty", LabelSlug.slug(""), "");
        check("all-whitespace", LabelSlug.slug("   "), "");
        check("multi-space", LabelSlug.slug("Hello   World"), "hello-world");
        check("mixed-case", LabelSlug.slug("HeLLo WoRLD"), "hello-world");
        check("tabs-and-newlines", LabelSlug.slug("a\tb\nc"), "a-b-c");
        check("leading-trailing", LabelSlug.slug("  padded  text  "), "padded-text");
        check("single-word", LabelSlug.slug("Label"), "label");
        check("already-slug", LabelSlug.slug("already-a-slug"), "already-a-slug");
        check("non-ascii-kept", LabelSlug.slug("繁體 ABC 測試"), "繁體-abc-測試");
        if (failed > 0) {
            System.out.println(failed + " case(s) FAILED");
            System.exit(1);
        }
        System.out.println("ALL PASS");
    }
}
EOF
javac --release 17 LabelSlug.java SlugTest.java && java SlugTest
